-- Municipios atendidos (P-02: 9 municipios; Córdoba de CO-03 era un error)
-- ---------------------------------------------------------------------

-- Sectores atendidos (P-02)
SELECT ID, 'Zona rural de Buenavista', 'ZONA_RURAL' FROM MUNICIPIO WHERE CODIGO_DANE = '63111';
SELECT ID, 'Pueblo Tapao', 'CORREGIMIENTO' FROM MUNICIPIO WHERE CODIGO_DANE = '63470';

-- ---------------------------------------------------------------------
-- Parámetros del sistema (RF-29). Valores por defecto de la sección 9 de la
-- especificación consolidada. TRG_PARAMETRO_CIU impide valores fuera de rango legal.
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- Roles (P-16)
