-- ---------------------------------------------------------------------
-- Permisos
-- ---------------------------------------------------------------------

-- Matriz rol-permiso (mínimo privilegio, RN-27)
SELECT R.ID, P.ID FROM ROL R JOIN PERMISO P ON (
       (R.CODIGO = 'CIUDADANO' AND P.CODIGO IN ('PORTAL_CONSULTAR','PORTAL_PAGAR','PORTAL_PQR'))
    OR (R.CODIGO = 'ASESOR' AND P.CODIGO IN (
            'USUARIO_CONSULTAR','USUARIO_CREAR','USUARIO_MODIFICAR','USUARIO_INACTIVAR',
            'PREDIO_GESTIONAR','MEDIDOR_GESTIONAR','CONTRATO_CONSULTAR','CONTRATO_CREAR','CONTRATO_CANCELAR',
            'ORDEN_GESTIONAR','LECTURA_REGISTRAR','LECTURA_CARGAR_ARCHIVO','LECTURA_REVISAR',
            'FACTURA_CONSULTAR','FACTURA_ANULAR','PAGO_CONSULTAR','PAGO_REGISTRAR_PRESENCIAL'))
    OR (R.CODIGO = 'GESTOR_PQR' AND P.CODIGO IN (
            'USUARIO_CONSULTAR','CONTRATO_CONSULTAR','FACTURA_CONSULTAR','PQR_CONSULTAR',
            'PQR_REGISTRAR_PRESENCIAL','PQR_TRAMITAR'))
    OR (R.CODIGO = 'JEFE_PQR' AND P.CODIGO IN (
            'USUARIO_CONSULTAR','CONTRATO_CONSULTAR','FACTURA_CONSULTAR','PQR_CONSULTAR',
            'PQR_REGISTRAR_PRESENCIAL','PQR_TRAMITAR','PQR_REASIGNAR','PQR_RECONOCER_SILENCIO','PQR_CONSULTAR_TODAS'))
    OR (R.CODIGO = 'GESTOR_CARTERA' AND P.CODIGO IN (
            'USUARIO_CONSULTAR','CONTRATO_CONSULTAR','FACTURA_CONSULTAR','PAGO_CONSULTAR','PAGO_REGISTRAR_PRESENCIAL',
            'CARTERA_CONSULTAR','ACUERDO_GESTIONAR','COBRO_GESTIONAR','REPORTE_CARTERA'))
    OR (R.CODIGO = 'GERENTE' AND P.CODIGO IN (
            'USUARIO_CONSULTAR','CONTRATO_CONSULTAR','FACTURA_CONSULTAR','PAGO_CONSULTAR','CARTERA_CONSULTAR',
            'PQR_CONSULTAR','PQR_CONSULTAR_TODAS','REPORTE_CARTERA','DASHBOARD_VER'))
    OR (R.CODIGO = 'ADMIN' AND P.CODIGO IN (
            'USUARIO_CONSULTAR','USUARIO_MODIFICAR','TARIFA_GESTIONAR','FACTURA_GENERAR_LOTE',
            'FUNCIONARIO_GESTIONAR','ROL_GESTIONAR','PARAMETRO_GESTIONAR','AUDITORIA_CONSULTAR')));

